file.content:
function saveLayout(){
  var layout = {};
  document.querySelectorAll('.grid').forEach(function(grid){
    layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
  });
  localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
  // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
  document.querySelectorAll('.grid').forEach(function(grid){
    localStorage.removeItem('coach888_order_' + grid.dataset.section);
  });
}

function loadLayout(){
  var raw = localStorage.getItem(LAYOUT_KEY);
  if (raw) {
    try { return JSON.parse(raw); } catch(e){}
  }
  // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
  var legacy = {}, found = false;
  document.querySelectorAll('.grid').forEach(function(grid){
    var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
    if (old) {
      try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
    }
  });
  return found ? legacy : null;
}

function saveTitles(){
  var titles = {};
  document.querySelectorAll('.section-title').forEach(function(t){
    var span = t.querySelector('.title-text');
    if (span) titles[t.dataset.section] = span.textContent.trim();
  });
  localStorage.setItem(TITLES_KEY, JSON.stringify(titles));
}

function applyTitles(){
  var raw = localStorage.getItem(TITLES_KEY);
  if (!raw) return;
  try {
    var titles = JSON.parse(raw);
    document.querySelectorAll('.section-title').forEach(function(t){
      var span = t.querySelector('.title-text');
      if (span && titles[t.dataset.section] != null) span.textContent = titles[t.dataset.section];
    });
  } catch(e){}
}

