/* ── 校友會分會選項 ── */
.chapter-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.chapter-pill {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1.5px solid #D4B8E0;
  border-radius: 12px;
  padding: 12px 16px;
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--text);
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.chapter-pill:hover {
  border-color: var(--purple);
  background: var(--bg-light);
}
.chapter-pill input {
  width: auto;
  margin: 0;
  accent-color: var(--purple);
}
.chapter-pill.selected {
  border-color: var(--purple);
  background: #F0E8F8;
}

.btn-submit {
  width: 100%;
  background: var(--orange);
  color: #fff;
  font-family: var(--font);

