  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  color: #fff;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.chapter-pill.selected .check-box {
  border-color: var(--purple);
