/* ── 傑出校友 ── */
.alumni {
  background: var(--bg);
  padding: 80px 0;
}
.alumni .section-title {
  text-align: center;
  margin-bottom: 16px;
}
.alumni-lead {
  text-align: center;
  color: var(--text-muted);
  max-width: 720px;
  margin: 0 auto 44px;
  font-size: 0.95rem;
}
.alumni-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}
@media (min-width: 560px) {
  .alumni-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 900px) {
  .alumni-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}
.alumni-card {
  background: #fff;
  border-radius: 16px;
  border: 1.5px solid var(--card-border);
  padding: 28px 20px 24px;
  text-align: center;
  box-shadow: 0 4px 16px rgba(139,90,150,0.10);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  cursor: default;
}
.alumni-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 10px 32px rgba(139,90,150,0.18);
}

