file.content:
.join-section {
  background: var(--bg);
  padding: 80px 0;
}
.form-card {
  background: #fff;
  border-radius: 20px;
  border: 1.5px solid var(--card-border);
  box-shadow: 0 8px 40px rgba(139,90,150,0.12);
  padding: 48px 40px;
  max-width: 560px;
  margin: 0 auto;
}
@media (max-width: 600px) {
  .form-card {
    padding: 32px 20px;
  }
}
.form-card .section-title {
  text-align: center;
  color: var(--purple);
  margin-bottom: 32px;
}
.form-group {
  margin-bottom: 20px;
}
.form-group label {
  display: block;
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 6px;
}
.required-star {
  color: var(--purple);
  margin-left: 2px;
}
.form-group input,
.form-group select {
  width: 100%;
  padding: 12px 16px;
  border: 1.5px solid #D4B8E0;
  border-radius: 10px;
  font-family: var(--font);
  font-size: 0.95rem;
  color: var(--text);
  background: #fff;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  outline: none;
  appearance: none;
  -webkit-appearance: none;
}
.form-group input:focus,
.form-group select:focus {
  border-color: var(--purple);
  box-shadow: 0 0 0 3px rgba(139,90,150,0.12);
}
.form-group input.error,
.form-group select.error {
  border-color: #E53E3E;
}
.error-msg {
  color: #E53E3E;
  font-size: 0.8rem;
  margin-top: 4px;
  display: none;
}

/* ── 校友會分會選項 ── */
.chapter-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.chapter-pill {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1.5px solid #D4B8E0;
  border-radius: 12px;

