  var shareBtn = document.getElementById('shareBtn');
  var copyLinkBtn = document.getElementById('copyLinkBtn');
  var shareUrl = location.href;
  var shareText = '南應人，換你回來了。一起找回同學、連結校友會，加入台南應用科技大學校友會召集令！';

  function flashBtnLabel(btn, text, duration) {
    var original = btn.textContent;
    btn.textContent = text;
    setTimeout(function() { btn.textContent = original; }, duration || 1800);
  }

  if (shareBtn) {
    shareBtn.addEventListener('click', function() {
      if (navigator.share) {
        navigator.share({ title: '台南應用科技大學校友會・召集令', text: shareText, url: shareUrl }).catch(function() {});
      } else {
        navigator.clipboard.writeText(shareText + ' ' + shareUrl).then(function() {
          flashBtnLabel(shareBtn, '✓ 已複製分享文字');
        }).catch(function() {
          flashBtnLabel(shareBtn, '複製失敗，請手動複製網址');
        });
      }
    });
  }

  if (copyLinkBtn) {
    copyLinkBtn.addEventListener('click', function() {
      navigator.clipboard.writeText(shareUrl).then(function() {
        flashBtnLabel(copyLinkBtn, '✓ 已複製連結');
      }).catch(function() {
        flashBtnLabel(copyLinkBtn, '複製失敗，請手動複製網址');
      });
    });
  }
