}

/* ── 校友會分會選項 ── */
.chapter-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.chapter-pill {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1.5px solid #D4B8E0;
  border-radius: 12px;
  padding: 12px 16px;
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--text);
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.chapter-pill:hover {
  border-color: var(--purple);
  background: var(--bg-light);
}
/* 原生radio的勾選外觀在部分瀏覽器/系統下不會顯示明顯的勾勾，教練反映「框框看起來能勾但勾不出東西」
   改成自畫方框+勾號，靠.selected class(JS已經在切換)控制顯示，不依賴瀏覽器原生樣式 */
.chapter-pill {
  position: relative;
}
.chapter-pill input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
}
.chapter-pill .check-box {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border: 1.5px solid #D4B8E0;
  border-radius: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  color: #fff;
  transition: border-color 0.2s ease, background 0.2s ease;
}
.chapter-pill.selected .check-box {
  border-color: var(--purple);
  background: var(--purple);
}
.chapter-pill.selected .check-box::after {
  content: '✓';
}
.chapter-pill.selected {
  border-color: var(--purple);
  background: #F0E8F8;
}

.btn-submit {
  width: 100%;
  background: var(--orange);

