function saveBadges(){
  var badges = {};
  document.querySelectorAll('.item').forEach(function(it){
    var b = it.querySelector('.badge');
    if (b) badges[it.dataset.url] = b.textContent.trim();
  });
  localStorage.setItem(BADGES_KEY, JSON.stringify(badges));
}

function applyBadges(){
  var raw = localStorage.getItem(BADGES_KEY);
  if (!raw) return;
  try {
    var badges = JSON.parse(raw);
    document.querySelectorAll('.item').forEach(function(it){
      var b = it.querySelector('.badge');
      if (b && badges[it.dataset.url] != null) b.textContent = badges[it.dataset.url];
    });
  } catch(e){}
}

