  var badges = {};
  document.querySelectorAll('.item').forEach(function(it){
    var b = it.querySelector('.badge');
    if (b) badges[it.dataset.url] = b.textContent.trim();
  });
  localStorage.setItem(BADGES_KEY, JSON.stringify(badges));
}

